using i64 = long long;
using pii = pair<int, int>;

template<typename T> bool chkmin(T& a, const T& b) { return a > b ? a = b, 1 : 0; }
template<typename T> bool chkmax(T& a, const T& b) { return a < b ? a = b, 1 : 0; }
template<typename T> T sq(T x) { return x * x; }

namespace fast_io {
    constexpr size_t BUF_SIZE = 1 << 21;
    char ibuf[BUF_SIZE], *ip = ibuf, *ie = ibuf;
    char obuf[BUF_SIZE], *op = obuf, *oe = obuf + BUF_SIZE - 1;

    inline int get_char() {
        if (ip == ie) {
            ie = ibuf + fread(ibuf, 1, BUF_SIZE, stdin);
            ip = ibuf;
        }
        return ip == ie ? EOF : *ip++;
    }

    inline void flush() {
        if (op != obuf) fwrite(obuf, 1, op - obuf, stdout), op = obuf;
    }

    inline void put_char(char c) {
        *op++ = c;
        if (op == oe) flush();
    }

    inline bool read(int& x) {
        int sign = 1; char c;
        while ((c = get_char()) < '0' || c > '9') if (c == '-') sign = -1; else if (c == EOF) return false;
        x = 0;
        while (c >= '0' && c <= '9') x = x * 10 + (c - '0'), c = get_char();
        x *= sign;
        return true;
    }

    inline bool read(long long& x) {
        int sign = 1; char c;
        while ((c = get_char()) < '0' || c > '9') if (c == '-') sign = -1; else if (c == EOF) return false;
        x = 0;
        while (c >= '0' && c <= '9') x = x * 10 + (c - '0'), c = get_char();
        x *= sign;
        return true;
    }

    inline bool read(char& c) {
        c = get_char();
        return c != EOF;
    }

    inline bool read(char* s) {
        char c;
        while ((c = get_char()) == ' ' || c == '\n' || c == '\r') if (c == EOF) return false;
        do { *s++ = c; } while ((c = get_char()) != ' ' && c != '\n' && c != '\r' && c != EOF);
        *s = '\0';
        return true;
    }

    template<typename T, typename... Args>
    inline bool read(T& x, Args&... args) { return read(x) && read(args...); }

    inline bool write(int x) {
        if (x == 0) { put_char('0'); return true; }
        if (x < 0) { put_char('-'); x = -x; }
        char buf[20]; int len = 0;
        while (x) { buf[len++] = x % 10 + '0'; x /= 10; }
        while (len) put_char(buf[--len]);
        return true;
    }

    inline bool write(long long x) {
        if (x == 0) { put_char('0'); return true; }
        if (x < 0) { put_char('-'); x = -x; }
        char buf[20]; int len = 0;
        while (x) { buf[len++] = x % 10 + '0'; x /= 10; }
        while (len) put_char(buf[--len]);
        return true;
    }

    inline bool write(char c) { put_char(c); return true; }

    template<typename T, typename... Args>
    inline bool write(T x, Args... args) { return write(x) && write(args...); }

    struct Flush { ~Flush() { flush(); } } flusher;
