using namespace fast_io;

const int MOD = 1000000007;

struct Bitset128 {
    uint64_t lo, hi;

    void set_bit(int pos) {
        if (pos < 64) lo |= (1ULL << pos);
        else hi |= (1ULL << (pos - 64));
    }

    void clear() { lo = hi = 0; }

    bool operator==(const Bitset128& other) const {
        return lo == other.lo && hi == other.hi;
    }

    bool operator[](int pos) const {
        return pos < 64 ? (lo >> pos) & 1 : (hi >> (pos - 64)) & 1;
    }

    Bitset128& operator|=(const Bitset128& other) {
        lo |= other.lo;
        hi |= other.hi;
        return *this;
    }
};

bool operator<(const Bitset128& a, const Bitset128& b) {
    return a.hi < b.hi || (a.hi == b.hi && a.lo < b.lo);
}

map<Bitset128, int> memo[8];
Bitset128 full_mask;

int n;
int a[11][11];
int f[11][1 << 11];

int mod_pow(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (1LL * result * base) % MOD;
        base = (1LL * base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int dfs(int depth, Bitset128 state) {
    if (depth == n) return state == full_mask;
    if (memo[depth].count(state)) return memo[depth][state];

    int result = 0;
    Bitset128 next_states[11];

    for (int j = 0; j < n; ++j) next_states[j].clear();

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (state[mask]) {
            for (int j = 0; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    next_states[j].set_bit(mask | (1 << j));
                }
            }
        }
    }

    for (int choice = 0; choice < (1 << n); ++choice) {
        Bitset128 new_state = state;
        for (int j = 0; j < n; ++j) {
            if (choice & (1 << j)) new_state |= next_states[j];
        }
        result = (result + 1LL * f[depth][choice] * dfs(depth + 1, new_state)) % MOD;
    }

    return memo[depth][state] = result;
}

int main() {
#ifdef QAQAutoMaton
    freopen("E.in", "r", stdin);
    freopen("E.out", "w", stdout);
#endif

    read(n);

    for (int i = 0; i < (1 << n); ++i) full_mask.set_bit(i);

    Bitset128 initial;
    initial.set_bit(0);

    int inv100 = mod_pow(100, MOD - 2);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            read(a[i][j]);
            a[i][j] = (1LL * a[i][j] * inv100) % MOD;
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            f[i][mask] = 1;
            for (int k = 0; k < n; ++k) {
                if (mask & (1 << k)) {
                    f[i][mask] = (1LL * f[i][mask] * a[k][i]) % MOD;
                } else {
                    f[i][mask] = (1LL * f[i][mask] * ((MOD + 1 - a[k][i]) % MOD)) % MOD;
                }
            }
        }
    }

    write(dfs(0, initial), '\n');

    return 0;
}
